package com.brightloop.discount;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;
@Entity @Table(name="discounts") public class Discount {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(nullable=false,unique=true,length=40) String code;@Column(nullable=false,length=120) String name;@Column(name="discount_type",nullable=false,length=20) String discountType;@Column(name="discount_value",nullable=false,precision=12,scale=4) BigDecimal value;@Column(name="starts_at") LocalDate startsAt;@Column(name="ends_at") LocalDate endsAt;@Column(name="max_uses") Integer maxUses;@Column(name="usage_count",nullable=false) int usageCount=0;@Column(nullable=false) boolean active=true;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();protected Discount(){}public Discount(String c,String n,String t,BigDecimal v,LocalDate s,LocalDate e,Integer max,boolean a){code=c.toUpperCase().trim();name=n;discountType=t;value=v;startsAt=s;endsAt=e;maxUses=max;active=a;}public Long getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getDiscountType(){return discountType;}public BigDecimal getValue(){return value;}public LocalDate getStartsAt(){return startsAt;}public LocalDate getEndsAt(){return endsAt;}public Integer getMaxUses(){return maxUses;}public int getUsageCount(){return usageCount;}public boolean isActive(){return active;}public void update(String n,String t,BigDecimal v,LocalDate s,LocalDate e,Integer max,boolean a){name=n;discountType=t;value=v;startsAt=s;endsAt=e;maxUses=max;active=a;}public boolean eligible(LocalDate date){return active&&(startsAt==null||!date.isBefore(startsAt))&&(endsAt==null||!date.isAfter(endsAt))&&(maxUses==null||usageCount<maxUses);}public void consume(){usageCount++;}}
